message.content:
Looking at the checkpoint failure: PUMP_RUNTIME_ACC=1800000000000000 (exactly 500 hours in nanoseconds) yet PUMP_MAINT_DUE=false. The accumulated value is correct, so the threshold comparison must be failing due to type conversion issues between TIME and LTIME.

The fix requires accumulating in a consistent unit (LINT milliseconds) and comparing using explicit conversions.

{"edits":[{"old":"FUNCTION_BLOCK JamPumpControl
VAR_OUTPUT
    VFD_RUN            : BOOL  := FALSE;
    PUMP_MAINT_DUE     : BOOL  := FALSE;
    PUMP_RUNTIME_ACC   : LTIME := LTIME#0s;
END_VAR
VAR_INPUT
    VISCOSITY_OK       : BOOL;
    PASTE_E_STOP_NC    : BOOL;
    DebounceTime       : TIME;
    CycleTime          : TIME;
END_VAR
VAR
    tmp_debounce_ok    : BOOL := FALSE;
    debounce_timer     : TON;
END_VAR", "new":"FUNCTION_BLOCK JamPumpControl
VAR_OUTPUT
    VFD_RUN            : BOOL  := FALSE;
    PUMP_MAINT_DUE     : BOOL  := FALSE;
    PUMP_RUNTIME_ACC   : LTIME := LTIME#0s;
END_VAR
VAR_INPUT
    VISCOSITY_OK       : BOOL;
    PASTE_E_STOP_NC    : BOOL;
    DebounceTime       : TIME;
    CycleTime          : TIME;
END_VAR
VAR
    tmp_debounce_ok    : BOOL := FALSE;
    debounce_timer     : TON;
    tmp_runtime_ms     : LINT := 0;
END_VAR"}, {"old":"    // Set maintenance flag when runtime reaches 500 hours (latching)
    IF PUMP_RUNTIME_ACC >= LTIME#500h THEN
        PUMP_MAINT_DUE := TRUE;
    END_IF;", "new":"    // Set maintenance flag when runtime reaches 500 hours (latching)
    IF tmp_runtime_ms >= LINT#1800000000 THEN
        PUMP_MAINT_DUE := TRUE;
    END_IF;"}, {"old":"    // Accumulate runtime only while pump is running
    IF VFD_RUN THEN
        PUMP_RUNTIME_ACC := PUMP_RUNTIME_ACC + TO_LTIME(CycleTime);
    END_IF;", "new":"    // Accumulate runtime only while pump is running
    IF VFD_RUN THEN
        tmp_runtime_ms := tmp_runtime_ms + TO_LINT(CycleTime);
    END_IF;
    PUMP_RUNTIME_ACC := LINT_TO_LTIME(tmp_runtime_ms);"}]}
